define(['jquery', 'core/templates'], function ($, Templates) {
    return {
        init: async (popup_title, user_fullname) => {
            let popup_result = await Templates.renderForPromise('auth_stripe/cancel_premium_popup', {
                popup_title: popup_title,
            });
            let popup = $(popup_result.html);
            let popup_appended = false;
            let button_link = false;

            let init_popup = () => {
                popup.find('.close_popup_btn').each((i, element) => {
                    $(element).click(() => {
                        button_link = false;
                        popup.hide();
                    });
                });
                popup.find('.confirm_btn').each((i, element) => {
                    $(element).click(() => {
                        if (!button_link){
                            alert('Something went wrong');
                            return;
                        }
                        window.location.href = button_link;
                    });
                });
            };

            $('.update-subscription-buttons-wrapper .update-subscription-button').each((i, element) => {
                let btn = $(element);
                btn.click(() => {
                    if (!popup_appended){
                        $(document.body).append(popup);
                        popup_appended = true;
                        init_popup(popup);
                    }
                    button_link = btn.attr('data-link');
                    console.log(element.textContent);
                    $('#update-tier-popup-action').text(element.textContent + ' for user "' + user_fullname + '"');
                    popup.show();
                });
            });
        },
    };
});